import Foundation

public enum DeployFiles {
    /// Cloudflare Workers Static Assets `_headers` (same syntax as Pages). Rules are additive per header name, so
    /// Cache-Control is set only where a path needs a non-default value.
    public static func headers() -> String {
        """
        # Generated by viadere-site. Cloudflare Workers Static Assets reads this file from the assets directory.
        /*
          Strict-Transport-Security: max-age=63072000; includeSubDomains
          Content-Security-Policy: \(Layout.csp); frame-ancestors 'none'
          X-Content-Type-Options: nosniff
          X-Frame-Options: DENY
          Referrer-Policy: no-referrer
          Permissions-Policy: accelerometer=(), autoplay=(), camera=(), display-capture=(), geolocation=(), gyroscope=(), magnetometer=(), microphone=(), payment=(), usb=(), browsing-topics=()
          Cross-Origin-Opener-Policy: same-origin
          Cross-Origin-Resource-Policy: same-origin

        /assets/site.*
          Cache-Control: public, max-age=31536000, immutable

        /assets/fonts/*
          Cache-Control: public, max-age=2592000

        /assets/media/*
          Cache-Control: public, max-age=2592000

        /.well-known/security.txt
          Content-Type: text/plain; charset=utf-8
          Cache-Control: public, max-age=3600

        /sitemap.xml
          Content-Type: application/xml; charset=utf-8

        """
    }

    /// RFC 9116. Contact and Expires are required fields; the values are placeholders until the security contact exists.
    public static func securityTxt(_ c: SiteConfig) -> String {
        """
        # Viadere security contact (RFC 9116). Placeholders must be replaced before launch.
        Contact: \(c.securityContact)
        Expires: \(c.securityExpires)
        Preferred-Languages: en
        Canonical: \(c.securityCanonical)
        Policy: \(c.securityPolicyURL)

        """
    }

    public static func robots(_ c: SiteConfig) -> String {
        "User-agent: *\nAllow: /\n\nSitemap: \(c.baseURL)/sitemap.xml\n"
    }

    public static func sitemap(_ c: SiteConfig, urls: [String]) -> String {
        var s = "<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n<urlset xmlns=\"http://www.sitemaps.org/schemas/sitemap/0.9\">\n"
        for u in urls.sorted() { s += "<url><loc>\(HTML.escape(c.baseURL + u))</loc></url>\n" }
        return s + "</urlset>\n"
    }
}
